            <td><EvidenceLinks records={records} requirementLabel={requirement.label} /></td>
          </tr>;
        })}</tbody>
      </table>
    </div>

    <h4>Dataset ranking</h4>
    <div className="table-scroll">
      <table className="data-table evidence-table">
